// Data shape: jdbc:<subprotocol>://<host>:<port>/<database>?<option>=<value>
String url = "jdbc:mysql://localhost:3306/bookings"
        + "?useSSL=false&serverTimezone=UTC&rewriteBatchedStatements=true";

// The text after jdbc: picks the driver, here mysql.
// 3306 is the MySQL default. SQLite has no host and no port.
String sqlite = "jdbc:sqlite:bookings.db";

try (Connection conn = DriverManager.getConnection(url, "root", System.getenv("DB_PASSWORD"))) {
    // The query string is read by the driver before the connection is opened.
    System.out.println(conn.getMetaData().getURL());
    System.out.println(conn.getMetaData().getDatabaseProductName()); // MySQL
} catch (SQLException e) {
    // No suitable driver means the classpath, not the server, is wrong.
    System.out.println(e.getMessage());
}

// Data shape: one of the five int constants on Connection.
// TRANSACTION_NONE, READ_UNCOMMITTED, READ_COMMITTED, REPEATABLE_READ, SERIALIZABLE.

try (Connection conn = DriverManager.getConnection(url, user, password)) {
    // Not every server supports every level. Check before setting.
    if (conn.getMetaData().supportsTransactionIsolationLevel(
            Connection.TRANSACTION_READ_COMMITTED)) {

        conn.setTransactionIsolation(Connection.TRANSACTION_READ_COMMITTED);
    }

    // MySQL defaults to REPEATABLE_READ, PostgreSQL to READ_COMMITTED.
    System.out.println("isolation: " + conn.getTransactionIsolation());

    conn.setAutoCommit(false);
    try {
        // ... statements ...
        conn.commit();
    } catch (SQLException e) {
        conn.rollback();
        throw e;
    } finally {
        // A pooled connection must go back with the level it arrived with.
        conn.setAutoCommit(true);
    }
}

// Data shape: Savepoint is an opaque handle tied to one open transaction.
conn.setAutoCommit(false);

Savepoint beforeOptionalStep = conn.setSavepoint("before_optional_step");

try {
    // Work that came before the savepoint is protected from this failure.
    try (PreparedStatement ps = conn.prepareStatement(
            "UPDATE bookings SET adults = ? WHERE booking_id = ?")) {

        ps.setInt(1, 4);
        ps.setInt(2, 7);
        int rows = ps.executeUpdate();

        if (rows != 1) {
            throw new SQLException("booking 7 does not exist");
        }
    }

    conn.releaseSavepoint(beforeOptionalStep); // success, marker no longer needed
} catch (SQLException e) {
    // Undo only the optional step, then keep the transaction alive.
    conn.rollback(beforeOptionalStep);
    System.out.println("optional step skipped: " + e.getMessage());
}

conn.commit(); // commits everything that survived

// Savepoint names must be unique inside the transaction.
// setSavepoint() with no argument returns an unnamed savepoint.

// Data shape: the column type decides the Types constant.
String sql = "UPDATE hotels SET description = ?, image = ? WHERE hotel_id = ?";

try (PreparedStatement ps = conn.prepareStatement(sql)) {
    // A null String means "no description", so send SQL NULL, not an empty string.
    ps.setNull(1, Types.VARCHAR);

    // Binary columns need their own type constant.
    ps.setNull(2, Types.BLOB);

    ps.setInt(3, 1);
    ps.executeUpdate();
}

// Types constants worth knowing: VARCHAR, CHAR, INTEGER, BIGINT, DECIMAL,
// DATE, TIMESTAMP, BOOLEAN, BLOB, and NULL for an untyped NULL.

// Data shape: int cannot hold NULL, so the getter substitutes 0.
String sql = "SELECT hotel_id, stars, description, adults FROM bookings WHERE booking_id = ?";

try (PreparedStatement ps = conn.prepareStatement(sql)) {
    ps.setInt(1, 7);

    try (ResultSet rs = ps.executeQuery()) {
        if (rs.next()) {
            int stars = rs.getInt("stars");

            // Check immediately. Any other getter resets the flag.
            boolean starsMissing = rs.wasNull();
            Integer nullableStars = starsMissing ? null : stars;

            // getString already returns null, no extra check needed.
            String description = rs.getString("description");

            System.out.println(nullableStars + " " + description);
        }
    }
}

// getBoolean returns false for NULL, getDouble returns 0.0, getDate returns null.
// Only the getDate case is unambiguous.

String sql = "INSERT INTO hotels (city, name, description, stars, owner_email) "
        + "VALUES (?, ?, ?, ?, ?)";

// The array names the columns you want back, in the order you want them.
try (PreparedStatement ps = conn.prepareStatement(sql, new String[]{"hotel_id"})) {
    ps.setString(1, "Budapest");
    ps.setString(2, "Hotel Sunrise");
    ps.setString(3, "Quiet hotel near the river");
    ps.setInt(4, 4);
    ps.setString(5, "owner@example.com");
    ps.executeUpdate();

    try (ResultSet keys = ps.getGeneratedKeys()) {
        if (keys.next()) {
            // Read by index for portability, by name when the driver allows it.
            int hotelId = keys.getInt(1);
            System.out.println("new hotel_id: " + hotelId);
        }
    }
}

// Statement.RETURN_GENERATED_KEYS is the shorter form when one key is enough.

// Data shape: one cursor, rows pulled in groups of 500 instead of all at once.
String sql = "SELECT booking_id, customer_email, start_date FROM bookings ORDER BY booking_id";

try (Connection conn = DriverManager.getConnection(url, user, password);
     PreparedStatement ps = conn.prepareStatement(sql)) {

    // MySQL streams only when the statement is forward-only and the fetch size is
    // positive; Connector/J also honours useCursorFetch=true in the URL.
    ps.setFetchSize(500);

    try (ResultSet rs = ps.executeQuery()) {
        long rows = 0;
        while (rs.next()) {
            rows++;
        }
        System.out.println("rows read: " + rows);
    }
}

// The default result set is forward-only, which is what streaming needs.

// Data shape: seconds, not milliseconds. 0 means no limit.
String sql = "SELECT hotel_id, name FROM hotels WHERE city = ?";

try (Connection conn = DriverManager.getConnection(url, user, password);
     PreparedStatement ps = conn.prepareStatement(sql)) {

    ps.setQueryTimeout(5); // cancel after five seconds
    ps.setString(1, "Budapest");

    try (ResultSet rs = ps.executeQuery()) {
        while (rs.next()) {
            System.out.println(rs.getInt("hotel_id") + " " + rs.getString("name"));
        }
    }
} catch (SQLTimeoutException e) {
    // A subclass of SQLException, so catch it first when the reaction differs.
    System.out.println("query cancelled after the timeout");
}

