// Data shape: rows with TABLE_CAT, TABLE_SCHEM, TABLE_NAME, TABLE_TYPE.
try (Connection conn = DriverManager.getConnection(url, user, password)) {
    DatabaseMetaData meta = conn.getMetaData();

    // Catalog is the database name in MySQL. null means "no filter".
    String catalog = conn.getCatalog();

    try (ResultSet tables = meta.getTables(catalog, null, "%", new String[]{"TABLE"})) {
        while (tables.next()) {
            System.out.println(tables.getString("TABLE_NAME")
                    + " (" + tables.getString("TABLE_TYPE") + ")");
        }
    }

    // Columns of one table, without running a query against it.
    try (ResultSet columns = meta.getColumns(catalog, null, "hotels", "%")) {
        while (columns.next()) {
            System.out.println(columns.getString("COLUMN_NAME")
                    + " " + columns.getString("TYPE_NAME")
                    + " nullable=" + columns.getString("IS_NULLABLE"));
        }
    }
}

// Data shape: List<String[]> -> counts per chunk, memory stays flat.
String sql = "INSERT INTO bookings "
        + "(customer_email, hotel_id, start_date, end_date, adults, children) "
        + "VALUES (?, ?, ?, ?, ?, ?)";

int chunk = 500;
int pending = 0;

try (Connection conn = DriverManager.getConnection(url, user, password);
     PreparedStatement ps = conn.prepareStatement(sql)) {

    conn.setAutoCommit(false);

    for (String[] row : rows) {
        ps.setString(1, row[0]);
        ps.setInt(2, Integer.parseInt(row[1]));
        ps.setDate(3, java.sql.Date.valueOf(row[2]));
        ps.setDate(4, java.sql.Date.valueOf(row[3]));
        ps.setInt(5, Integer.parseInt(row[4]));
        ps.setInt(6, Integer.parseInt(row[5]));
        ps.addBatch();
        pending++;

        if (pending == chunk) {
            int[] counts = ps.executeBatch();
            ps.clearBatch();   // release the parameter sets the driver kept
            pending = 0;
        }
    }

    if (pending > 0) {
        ps.executeBatch();
    }

    conn.commit();
}

try (Connection conn = DriverManager.getConnection(url, user, password);
     PreparedStatement ps = conn.prepareStatement(
             "INSERT INTO hotels (city, name, description, stars, owner_email) "
                     + "VALUES (?, ?, ?, ?, ?)")) {

    ps.setString(1, "Vienna");
    ps.setString(2, "Hotel Ring");
    ps.setString(3, "Small hotel beside the ring road");
    ps.setInt(4, 4);
    ps.setString(5, "owner@example.com");
    ps.executeUpdate();

} catch (SQLIntegrityConstraintViolationException e) {
    // Class 23 is an integrity constraint, usually a duplicate key or a broken FK.
    System.out.println("state " + e.getSQLState() + ", code " + e.getErrorCode());
    System.out.println(e.getMessage());
} catch (SQLException e) {
    // Log all three. The message alone rarely names the constraint.
    System.out.println("state " + e.getSQLState());     // e.g. 42S02
    System.out.println("vendor code " + e.getErrorCode()); // e.g. 1146
    System.out.println("message " + e.getMessage());

    // A batch can attach one exception per failed statement.
    for (SQLException next = e.getNextException(); next != null; next = next.getNextException()) {
        System.out.println("also: " + next.getMessage());
    }

    throw new IllegalStateException("hotel insert failed", e); // keep the cause
}

// Data shape: LocalDate -> DATE column, with no java.sql.Date in between.
String sql = "INSERT INTO bookings "
        + "(customer_email, hotel_id, start_date, end_date, adults, children) "
        + "VALUES (?, ?, ?, ?, ?, ?)";

try (PreparedStatement ps = conn.prepareStatement(sql)) {
    ps.setString(1, "jane.doe@example.com");
    ps.setInt(2, 1);

    // JDBC 4.2 sends LocalDate directly when the driver understands it.
    ps.setObject(3, LocalDate.of(2024, 5, 1), Types.DATE);
    ps.setObject(4, LocalDate.of(2024, 5, 4), Types.DATE);

    ps.setInt(5, 2);
    ps.setInt(6, 0);
    ps.executeUpdate();
}

